update wms_loc_attr
   set loc_usage = #{f.locUsage}, stock_yn = #{f.stockYn}, pick_seq = #{f.pickSeq}, mix_item_yn = #{f.mixItemYn},
       mix_lot_yn = #{f.mixLotYn}, default_status = #{f.defaultStatus}, feed_node_id = #{f.feedNodeId}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where node_id = #{nodeId} and row_ver = #{f.rowVer}
